CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,role TEXT NOT NULL CHECK(role IN ('ADMIN','MEDIADOR')),username TEXT NOT NULL UNIQUE,matricula TEXT UNIQUE,nombre TEXT NOT NULL,apellido TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',telefono TEXT NOT NULL DEFAULT '',photo TEXT NOT NULL DEFAULT '',password BLOB NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS whitelist(matricula TEXT PRIMARY KEY,nombre TEXT NOT NULL,apellido TEXT NOT NULL,email TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires_at);
CREATE TABLE IF NOT EXISTS blocked_days(sede TEXT NOT NULL,date TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',PRIMARY KEY(sede,date));
CREATE TABLE IF NOT EXISTS exports(id INTEGER PRIMARY KEY,date_from TEXT NOT NULL,date_to TEXT NOT NULL,created_at TEXT NOT NULL,admin_id INTEGER NOT NULL REFERENCES users(id),filename TEXT NOT NULL,count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS mediations(id INTEGER PRIMARY KEY,sede TEXT NOT NULL,date TEXT NOT NULL,start TEXT NOT NULL,m1 INTEGER NOT NULL REFERENCES users(id),m2 INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,case_number TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('RESERVADA','INICIADA','FINALIZADA','FIRMADA','CANCELADA_POR_ADMIN')),result TEXT NOT NULL DEFAULT '' CHECK(result IN ('','CON_ACUERDO','SIN_ACUERDO','INCOMPARECENCIA')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,exported_at TEXT,export_id INTEGER REFERENCES exports(id),CHECK(m1<>m2),CHECK(state NOT IN ('FINALIZADA','FIRMADA') OR result<>''));
CREATE INDEX IF NOT EXISTS mediations_slot ON mediations(sede,date,start);
CREATE INDEX IF NOT EXISTS mediations_m1 ON mediations(m1,date);
CREATE INDEX IF NOT EXISTS mediations_m2 ON mediations(m2,date);
CREATE TABLE IF NOT EXISTS news(id INTEGER PRIMARY KEY,title TEXT NOT NULL,content TEXT NOT NULL,image TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0,publication_date TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY,actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,entity_id INTEGER,created_at TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '');
INSERT OR IGNORE INTO schema_migrations(version) VALUES(1);
